import { PathEffect, FillEffect, Color } from "retiam";

// 1. Single effect
const dashed = PathEffect.Dashed(0.5, 0.3);

// 2. Chained effects (Order matters!)
const trail = PathEffect.Dashed([1, 1, 2, 1], 0, true)
                        .Glow(0.005)
                        .Taper(0, 1)
                        .Comet(1);

// 3. Applying to entities
const trace = new TracePath({
    target: dot,
    shader: trail // Can be passed to any entity that accepts `shader`
});

// Cascades gradient -> glow -> dashed into one single compiled shader
const cascadedStroke = PathEffect.combine([
    PathEffect.Gradient([new Color(0, 1, 1), new Color(1, 0, 1)]),
    PathEffect.Glow(0.3),
    PathEffect.Dashed(0.5, 0.2)
]);

// Cascades checkerboard -> linear gradient
const cascadedFill = FillEffect.combine([
    FillEffect.Checkerboard(new Color(0.2, 0.2, 0.2), new Color(0.3, 0.3, 0.3), 0.5),
    FillEffect.GradientLinear([new Color(1, 0, 0, 0.5), new Color(0, 0, 1, 0.5)], 0, 0, 1, 1)
]);

// Both compile to WGSL strings standalone (no Entity required):
const strokeWgsl = cascadedStroke.compile();
const fillWgsl = cascadedFill.compile();

const path = new Path("M 0 0 L 10 0", {
    strokeShader: [
        PathEffect.Gradient([new Color(0, 1, 1), new Color(1, 0, 1)]),
        PathEffect.Dashed(0.5, 0.2)
    ],
    fillShader: FillEffect.GradientRadial(
        [new Color(1, 1, 0, 0.8), new Color(1, 0, 0, 0)],
        0, 0, 2
    )
});
